fieldsInfo.css:
/* 五線譜（A4 縦 150 dpi = 1240×1754px）。記号は SVG（計算式が段ごとに作る）、字は HTML */
.ms-page { box-sizing: border-box; padding: 64px 0 0 !important; background: #fff; color: #111;
  font-family: "Hiragino Sans", "Hiragino Kaku Gothic ProN", "Yu Gothic", "Meiryo", sans-serif; }
.ms-head { position: relative; height: 168px; margin: 0 96px 0 96px; }
.ms-title { text-align: center; font: bold 46px/1.3 "Hiragino Mincho ProN", "Yu Mincho", "MS Mincho", serif; padding-top: 6px; }
.ms-sub { text-align: center; font-size: 20px; color: #444; height: 28px; }
.ms-tempo { position: absolute; left: 0; bottom: 14px; font-size: 21px; }
.ms-cred { position: absolute; right: 0; bottom: 14px; font-size: 21px; text-align: right; }
.ms-cred span { margin-left: 28px; }
.ms-err, .ms-note { margin: 0 96px 10px 96px; padding: 6px 14px; font-size: 18px; line-height: 25px; border-radius: 6px; }
.ms-err { color: #c00; border: 2px solid #e66; background: #fff5f5; }
.ms-note { color: #555; border: 1.5px solid #bbb; background: #fafafa; }
.ms-ih { font-weight: bold; }
.ms-sys { position: relative; width: 1240px; }
.ms-sys img { position: absolute; left: 0; top: 0; }
.ms-sys span { position: absolute; width: 120px; margin-left: -60px; text-align: center; white-space: nowrap; }
.ms-sys .ly { font-size: 21px; line-height: 26px; }
.ms-sys .hy { display: flex; margin-left: 0; font-size: 21px; line-height: 26px; color: #444; }
.ms-sys .hy i { visibility: hidden; font-style: normal; font-size: 50%; }
.ms-sys .hy b { flex: 1; font-weight: normal; text-align: center; }
.ms-sys .dr { top: 134px; font-size: 15px; line-height: 20px; color: #555; }
.ms-pn { position: absolute; left: 0; right: 0; bottom: 24px; text-align: center; font-size: 16px; color: #777; }
.ms-h00 { height: 144px; }
.ms-h01 { height: 172px; }
.ms-h02 { height: 200px; }
.ms-h03 { height: 228px; }
.v10 { top: 134px; }
.v20 { top: 162px; }
.v30 { top: 190px; }
.ms-h10 { height: 166px; }
.ms-h11 { height: 194px; }
.ms-h12 { height: 222px; }
.ms-h13 { height: 250px; }
.v11 { top: 156px; }
.v21 { top: 184px; }
.v31 { top: 212px; }

